const job = $input.first().json;
const pending = ['queued', 'running'].includes(job.status);
const report = job.report || {};
return [{ json: { prepared_only: true, sent: false, job_id: job.id, status: job.status, polling_timed_out: pending, subject: `Metric Detective: ${pending ? 'poll limit reached' : job.status}`, body: pending ? 'The job is still pending. Inspect the API or UI; this workflow did not cancel it.' : (report.findings || []).map(f => f.text).join('\n') || 'Inspect report limitations or job error.', report_url: $('Configure request').first().json.api_url + '/investigations/' + job.id + '/report.html' } }];
